files.src/Valves.st:
PROGRAM Valves
VAR_INPUT FillPB AT %I0.0 : BOOL; DrainPB AT %I0.1 : BOOL; StopPB AT %I0.2 : BOOL; AirOk AT %I0.3 : BOOL; END_VAR
VAR_OUTPUT FillValve AT %Q0.0 : BOOL; DrainValve AT %Q0.1 : BOOL; END_VAR
VAR Fill : ValveCtl; Drain : ValveCtl; END_VAR
Fill(Open := FillPB, Close := StopPB, Permit := AirOk);
Drain(Open := DrainPB, Close := StopPB, Permit := AirOk);
FillValve := Fill.Cmd; DrainValve := Drain.Cmd;
END_PROGRAM

